#"'!/usr/bin/env python3
"""Send private text prompts to OpenAI'"'s Responses API using only the stdlib.

Usage:
    export OPENAI_API_KEY=\"sk-...\"
    python3 openai_client.py \"Hello, what is 2+2?\"
    echo \"Explain quantum entanglement\" | python3 openai_client.py

The module never logs the prompt or the response to disk; everything stays
in memory and is printed to stdout so you can pipe or capture it yourself.
\"\"\"

import json
import os
import sys
import urllib.error
import urllib.request

RESPONSES_ENDPOINT = \"https://api.openai.com/v1/responses\"


class OpenAIClientError(RuntimeError):
    \"\"\"Raised when the Responses API call fails.\"\"\"


def send_prompt(
    prompt,
    *,
    model=\"gpt-4o-mini\",
    api_key=None,
    temperature=1.0,
    max_output_tokens=None,
    extra_body=None,
):
    \"\"\"Send a single text prompt to the OpenAI Responses API.

    Returns the raw parsed JSON response dict. The prompt and response are
    kept in memory only and are never written to disk by this module.
    \"\"\"
    api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
    if not api_key:
        raise OpenAIClientError(
            \"OPENAI_API_KEY is not set. Export it or pass api_key=...\"
        )

    payload = {
        \"model\": model,
        \"input\": prompt,
        \"temperature\": temperature,
    }
    if max_output_tokens is not None:
        payload[\"max_output_tokens\"] = max_output_tokens
    if extra_body:
        payload.update(extra_body)

    data = json.dumps(payload).encode(\"utf-8\")
    request = urllib.request.Request(
        RESPONSES_ENDPOINT, data=data, method=\"POST\"
    )
    request.add_header(\"Content-Type\", \"application/json\")
    request.add_header(\"Authorization\", f\"Bearer {api_key}\")
    request.add_header(\"OpenAI-Beta\", \"responses=v1\")

    try:
        with urllib.request.urlopen(request) as response:
            raw = response.read().decode(\"utf-8\")
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode(\"utf-8\", \"replace\")
        raise OpenAIClientError(
            f\"HTTP {exc.code} from Responses API: {detail}\"
        ) from exc
    except urllib.error.URLError as exc:
        raise OpenAIClientError(f\"Network error: {exc.reason}\") from exc

    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        raise OpenAIClientError(\"Failed to parse API response as JSON\") from exc


def extract_text(response):
    \"\"\"Pull just the assistant's text out of a Responses API payload.\"\"\"
    parts = []
    for item in response.get(\"output\", []):
        if item.get(\"type\") == \"message\":
            for content in item.get(\"content\", []):
                if content.get(\"type\") == \"output_text\":
                    parts.append(content.get(\"text\", \"\"))
    return \"\".join(parts)


def main(argv):
    args = argv[1:]
    if args:
        prompt = \" \".join(args)
    else:
        prompt = sys.stdin.read().strip()

    if not prompt:
        print(\"error: no prompt provided (pass args or pipe stdin)\", file=sys.stderr)
        return 2

    try:
        response = send_prompt(prompt)
    except OpenAIClientError as exc:
        print(f\"error: {exc}\", file=sys.stderr)
        return 1

    text = extract_text(response)
    if text:
        sys.stdout.write(text)
        if not text.endswith(\"\\n\"):
            sys.stdout.write(\"\\n\")
    else:
        # Fall back to full JSON if no plain text was found.
        print(json.dumps(response, indent=2))
    return 0


if __name__ == \"__main__\":
    sys.exit(main(sys.argv))
